public class Maximizer {

    public static <T extends Comparable<T>> T max(java.util.List<T> items) {
        T best = null;
        for (T item : items) {
            if (best == null || item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }

    public static <T> T lastOrDefault(java.util.List<T> items, T fallback) {
        if (items.isEmpty()) {
            return fallback;
        }
        return items.get(items.size() - 1);
    }
}
